-- Document API schema. IDs are BIGINT (Snowflake generated by the service).
CREATE TABLE documents (
  id                    BIGINT PRIMARY KEY,
  tenant_id             BIGINT NOT NULL,
  organization_id       BIGINT NOT NULL,
  workspace_id          BIGINT NOT NULL,
  page_id               BIGINT NOT NULL UNIQUE,
  schema_version        INTEGER NOT NULL,
  current_revision_no   INTEGER NOT NULL,
  draft_revision_id     BIGINT,
  published_revision_id BIGINT,
  created_by            BIGINT NOT NULL,
  created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_documents_scope ON documents(tenant_id, organization_id, workspace_id);

CREATE TABLE document_revisions (
  id            BIGINT PRIMARY KEY,
  document_id   BIGINT NOT NULL REFERENCES documents(id),
  revision_no   INTEGER NOT NULL,
  document_json JSONB NOT NULL,
  checksum      VARCHAR(128) NOT NULL,
  source        VARCHAR(32) NOT NULL CHECK (source IN ('EDITOR','AI','IMPORT','RESTORE','MIGRATION','SYSTEM')),
  created_by    BIGINT NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (document_id, revision_no)
);
CREATE INDEX idx_revisions_document ON document_revisions(document_id, revision_no DESC);

-- Revisions are immutable: block UPDATE and DELETE at the database level.
CREATE FUNCTION forbid_revision_mutation() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'document_revisions rows are immutable';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_revisions_immutable
  BEFORE UPDATE OR DELETE ON document_revisions
  FOR EACH ROW EXECUTE FUNCTION forbid_revision_mutation();

CREATE TABLE document_action_batches (
  id              BIGINT PRIMARY KEY,
  document_id     BIGINT NOT NULL REFERENCES documents(id),
  revision_id     BIGINT NOT NULL,
  tenant_id       BIGINT NOT NULL,
  actor_id        BIGINT NOT NULL,
  source          VARCHAR(32) NOT NULL,
  request_id      VARCHAR(64),
  idempotency_key VARCHAR(255),
  actions         JSONB NOT NULL,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_action_batches_document ON document_action_batches(document_id, created_at DESC);

CREATE TABLE document_references (
  id          BIGINT PRIMARY KEY,
  document_id BIGINT NOT NULL REFERENCES documents(id),
  tenant_id   BIGINT NOT NULL,
  ref_type    VARCHAR(32) NOT NULL,   -- media | data_source
  ref_key     VARCHAR(128) NOT NULL,  -- asset id or data-source type
  node_id     BIGINT NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_references_document ON document_references(document_id);
CREATE INDEX idx_references_lookup ON document_references(tenant_id, ref_type, ref_key);

CREATE TABLE document_locks (
  id          BIGINT PRIMARY KEY,
  document_id BIGINT NOT NULL UNIQUE REFERENCES documents(id),
  tenant_id   BIGINT NOT NULL,
  actor_id    BIGINT NOT NULL,
  expires_at  TIMESTAMPTZ NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE document_schema_versions (
  version     INTEGER PRIMARY KEY,
  description TEXT NOT NULL,
  applied_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
INSERT INTO document_schema_versions(version, description) VALUES (1, 'Initial typed node tree');

CREATE TABLE outbox_events (
  id             BIGINT PRIMARY KEY,
  tenant_id      BIGINT NOT NULL,
  aggregate_type VARCHAR(32) NOT NULL,
  aggregate_id   BIGINT NOT NULL,
  event_type     VARCHAR(64) NOT NULL,
  payload        JSONB NOT NULL,
  status         VARCHAR(16) NOT NULL DEFAULT 'PENDING',
  attempts       INTEGER NOT NULL DEFAULT 0,
  last_error     TEXT,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  published_at   TIMESTAMPTZ
);
CREATE INDEX idx_outbox_pending ON outbox_events(created_at) WHERE status = 'PENDING';

CREATE TABLE idempotency_keys (
  id              BIGINT PRIMARY KEY,
  tenant_id       BIGINT NOT NULL,
  actor_id        BIGINT NOT NULL,
  operation       VARCHAR(64) NOT NULL,
  idempotency_key VARCHAR(255) NOT NULL,
  request_hash    VARCHAR(64) NOT NULL,
  status          VARCHAR(16) NOT NULL DEFAULT 'SUCCEEDED',
  response_status INTEGER NOT NULL,
  response_json   JSONB NOT NULL,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at      TIMESTAMPTZ NOT NULL,
  UNIQUE (tenant_id, actor_id, operation, idempotency_key)
);
